package com.github.nyabanban.fuji.emulator.components.sdhost

import com.github.nyabanban.fuji.emulator.api.*
import org.junit.jupiter.api.Test
import java.nio.file.Path
import kotlin.test.*

class SdHostFactoryTest {
 private fun input(a:Any=0L,b:Any=0xa55a0005L)=mapOf<String,Any>("schema" to 1,"profile" to SdHostFactory.PROFILE,"initialWords" to mapOf("0" to a,"1" to b))
 private class Context(var data:Map<String,Any>):ComponentContext {
  var tick=10L;var reads=0;val entries=mutableMapOf<String,Any>();override val directory=Path.of("unused-sd-host-test");override val clock=EmulationClock{tick}
  override val ports=object:Ports{override fun<T:Any>register(owner:String,name:String,type:Class<T>,port:T){check(entries.putIfAbsent(name,port)==null)};override fun<T:Any>find(name:String,type:Class<T>):T?=entries[name]?.let{type.cast(it)};override fun removeOwner(owner:String)=error("unexpected remove")}
  override val events=object:EventChannel{override fun publish(event:ComponentEvent)=error("no invented event/IRQ");override fun subscribe(listener:(ComponentEvent)->Unit):AutoCloseable=error("no subscription")}
  override fun dataPath(relative:String)=directory.resolve(relative)
  override fun readData(relative:String):Map<String,Any>{assertEquals("input.yaml",relative);reads++;return data}
 }
 private fun create(c:Context,active:Boolean=true):HardwareComponent{val factory=SdHostFactory();return factory.create(c,factory.descriptor.settings.associate{it.key to it.default}+mapOf("profile" to if(active)SdHostFactory.PROFILE else "disabled","inputFile" to if(active)"input.yaml" else ""))}
 @Test fun disabledPublishesNothingAndDoesNotReadInput(){val c=Context(input());val h=create(c,false);h.start();assertEquals(0,c.reads);assertTrue(c.entries.isEmpty());assertTrue(h.additionalMmioPorts().isEmpty());assertTrue(h.interruptRoutes().isEmpty());assertEquals(false,h.state()["enabled"])}
 @Test fun bothExplicitInputsAreFrozenAndOnlyExactWordsAreExposed(){val words=mutableMapOf("0" to 0L,"1" to 0xffffffffL);val c=Context(input()+mapOf("initialWords" to words));val h=create(c);h.start();words["1"]=1;assertEquals(listOf(SdHostFactory.port(0),SdHostFactory.port(1)),h.additionalMmioPorts());assertEquals(1,c.reads);assertEquals(0xffffffffL,c.ports.find(SdHostFactory.port(1),MmioDevice::class.java)!!.read(0,4));assertTrue(h.interruptRoutes().isEmpty());assertEquals(false,h.state()["cardProtocolQualified"])}
 @Test fun fullU32RetentionStaysIndependentPerSlotAndRecordsOwnerContext(){val c=Context(input());c.entries["cpu.execution-location"]=ExecutionLocationSource{ExecutionLocation(2,0x5af98)};val h=create(c);h.start();val a=c.ports.find(SdHostFactory.port(0),MmioDevice::class.java)!!;val b=c.ports.find(SdHostFactory.port(1),MmioDevice::class.java)!!;for(v in listOf(0L,1L,0xffffffffL,0xa55a0f05L)){a.write(0,4,v);assertEquals(v,a.read(0,4));assertEquals(0xa55a0005L,b.read(0,4))};assertEquals(4L,h.state()["writeCount"]);val access=(h.state()["accesses"]as List<*>).last()as Map<*,*>;assertEquals(2,access["core"]);assertEquals(0x5af98L,access["pcVirtual"]);assertEquals(85,a.clockOrder);assertEquals(0,a.clockIndex);assertEquals(1,b.clockIndex)}
 @Test fun malformedAndIncompleteInputsRefuseBeforeAnyPublication(){for(key in input().keys){val c=Context(input()-key);assertFails{create(c)};assertTrue(c.entries.isEmpty())};for(data in listOf(input()+mapOf("schema" to 1.0),input()+mapOf("profile" to "bad"),input()+mapOf("extra" to 0),input()+mapOf("initialWords" to mapOf("0" to 0)),input()+mapOf("initialWords" to mapOf("0" to 0,"1" to 0,"2" to 0)))){val c=Context(data);assertFails{create(c)};assertTrue(c.entries.isEmpty())};for(v in listOf(-1L,0x100000000L,1.0,true,"0")){val c=Context(input(v));assertFails{create(c)};assertTrue(c.entries.isEmpty())};val c=Context(input());c.entries[SdHostFactory.port(1)]=object:MmioDevice{override fun read(offset:Long,size:Int)=0L;override fun write(offset:Long,size:Int,value:Long){}};assertFails{create(c)};assertEquals(1,c.entries.size)}
 @Test fun unsupportedWidthsHolesBadValuesAndBadClockAreAtomicFailures(){val c=Context(input());val h=create(c);h.start();val p=c.ports.find(SdHostFactory.port(0),MmioDevice::class.java)!!;val before=h.state();for((offset,width)in listOf(-4L to 4,1L to 4,4L to 4,0L to 1,0L to 2,0L to 8)){assertFails{p.read(offset,width)};assertFails{p.write(offset,width,0)};assertEquals(before,h.state())};for(v in listOf(-1L,0x100000000L)){assertFails{p.write(0,4,v)};assertEquals(before,h.state())};c.tick=-1;assertFails{p.read(0,4)};assertFails{p.write(0,4,1)};assertEquals(before,h.state());c.tick=1;c.entries["cpu.execution-location"]=ExecutionLocationSource{error("location refusal")};assertFails{p.write(0,4,1)};assertEquals(before,h.state())}
 @Test fun boundedRetentionAndLifecycleNeverInventEventsOrReconfigureLive(){val c=Context(input());val h=create(c);h.start();val p=c.ports.find(SdHostFactory.port(0),MmioDevice::class.java)!!;repeat(300){c.tick=it.toLong();assertEquals(0L,p.read(0,4))};assertEquals(300L,h.state()["accessCount"]);assertEquals(256,(h.state()["accesses"]as List<*>).size);assertEquals(true,h.state()["accessLogTruncated"]);assertFails{h.applySettings(mapOf("inputFile" to "other.yaml"))};h.close();h.close();assertFails{p.read(0,4)};assertFails{p.write(0,4,0)};assertFails{h.start()}}
}
